mapper.select:
SELECT product_type
FROM kb_product
WHERE product_code = #{productCode}

SELECT base_date, close_price
FROM etf_history_price
WHERE product_id = #{productId}
  AND base_date BETWEEN #{from} AND #{to}
ORDER BY base_date ASC
LIMIT 1

SELECT base_date, close_price
FROM etf_history_price
WHERE product_id = #{productId}
  AND base_date <= #{to}
ORDER BY base_date DESC
LIMIT 1

mapper.update:
UPDATE etf detail
JOIN kb_product_version pv
  ON pv.kb_product_version_id = detail.kb_product_version_id
SET detail.annual_return_10y = #{annualReturn10yPercent}
WHERE pv.kb_product_data_version_id = #{targetDataVersionId}
  AND pv.product_id = #{productId}
